import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { projectLogic } from 'scenes/projectLogic'
import { teamLogic } from 'scenes/teamLogic'

import type { TeamPublicType, TeamType } from '~/types'

import { platformAlertsList } from 'products/alerts_platform/frontend/generated/api'
import type { PlatformAlertConfigurationApi } from 'products/alerts_platform/frontend/generated/api.schemas'

const ALERT_OPTIONS_PAGE_SIZE = 100

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface alertTriggerOptionsLogicValues {
    currentProjectId: number | null // projectLogic
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    alerts: PlatformAlertConfigurationApi[] | null
    alertsLoading: boolean
    inMainEnvironment: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface alertTriggerOptionsLogicActions {
    loadCurrentProjectSuccess: (
        currentProject: null | import('~/types').ProjectType,
        payload?: any
    ) => {
        currentProject: null | import('~/types').ProjectType
        payload?: any
    } // projectLogic
    loadAlerts: (_: void) => void
    loadAlertsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAlertsSuccess: (
        alerts: PlatformAlertConfigurationApi[] | null,
        payload?: void
    ) => {
        alerts: PlatformAlertConfigurationApi[] | null
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface alertTriggerOptionsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        inMainEnvironment: (currentTeam: TeamPublicType | TeamType | null) => boolean
    }
}

export type alertTriggerOptionsLogicType = MakeLogicType<
    alertTriggerOptionsLogicValues,
    alertTriggerOptionsLogicActions,
    Record<string, any>,
    alertTriggerOptionsLogicMeta
>

export const alertTriggerOptionsLogic = kea<alertTriggerOptionsLogicType>([
    path([
        'products',
        'workflows',
        'frontend',
        'Workflows',
        'hogflows',
        'registry',
        'triggers',
        'alertTriggerOptionsLogic',
    ]),
    connect(() => ({
        values: [projectLogic, ['currentProjectId'], teamLogic, ['currentTeam']],
        actions: [projectLogic, ['loadCurrentProjectSuccess']],
    })),
    loaders(({ values }) => ({
        alerts: [
            null as PlatformAlertConfigurationApi[] | null,
            {
                loadAlerts: async (_: void, breakpoint): Promise<PlatformAlertConfigurationApi[] | null> => {
                    if (!values.currentProjectId) {
                        return null
                    }
                    if (!values.inMainEnvironment) {
                        return []
                    }
                    // Every page, so the picker can offer any alert the project has, not only the newest.
                    const alerts: PlatformAlertConfigurationApi[] = []
                    for (let offset = 0; ; offset += ALERT_OPTIONS_PAGE_SIZE) {
                        const page = await platformAlertsList(String(values.currentProjectId), {
                            limit: ALERT_OPTIONS_PAGE_SIZE,
                            offset,
                        })
                        // Stops the scan once the panel closes or a newer load starts.
                        breakpoint()
                        alerts.push(...page.results)
                        if (!page.next || page.results.length === 0) {
                            return alerts
                        }
                    }
                },
            },
        ],
    })),
    selectors({
        // Alerts belong to a project's main environment, so a trigger saved in another one never runs.
        inMainEnvironment: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): boolean =>
                !currentTeam || currentTeam.id === currentTeam.project_id,
        ],
    }),
    listeners(({ actions }) => ({
        loadAlertsFailure: ({ error }) => {
            posthog.captureException(error, { scope: 'alertTriggerOptionsLogic.load' })
        },
        // The logic can mount before the project resolves; retry the load once it does.
        loadCurrentProjectSuccess: () => {
            actions.loadAlerts()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadAlerts()
    }),
])
